source_vflip='''def transform(grid):
    g = [row[:] for row in grid]
    n, m = len(g), len(g[0])
    r0, c0 = next((r, c) for r in range(n) for c in range(m) if g[r][c] == 3)
    if c0 in (4, 6):
        base_r = base_c = 4
        pattern = [[2,3,4,5],[2],[2,4,5,6],[2,4,6],[2,4,6],[2,6],[2,3,4,5,6]]
    else:
        base_r, base_c = 4, 5
        pattern = [[1,3,4,5,6,7,8,9],[1,3,9],[1,3,5,6,7,9],[1,3,5,7,9],[1,3,5,7,9],[1,3,7,9],[1,3,4,5,6,7,9],[1,9],[1,2,3,4,5,6,7,8,9],[],list(range(11)]]
        if r0 == 5:
            pattern = [[3,4,5,6,7,8,9],[3,9]] + pattern[2:]
    for dr, cols in enumerate(pattern):
        for c in cols:
            if c0 == 6:
                r, cc = r0 - (dr - base_r), c0 + (c - base_c)
            else:
                r, cc = dr + (r0 - base_r), c + (c0 - base_c)
            if 0 <= r < n and 0 <= cc < m and g[r][cc] != 2:
                g[r][cc] = 3
    return g
'''
